"""All rooted trees with at most NMAX vertices (generated by size from multisets of smaller rooted trees).
For each branch b: the telescoping identity g(b) = h(y_b) + sum_v sigma_v (eq. bg-tele), evaluated in floating
point; the list of branches with sum of slacks < 1e-13 (Proposition bg-zero: exactly leaf, cherry, A_5); the
non-atom gap delta(b) - 0.01426 * #minimal non-atoms; and, for each cap C, min g - eta_C |b| - H(y_b).
Usage: python3 exhaustive_rooted.py NMAX
"""
from trees import *
import time
NMAX=int(sys.argv[1])
# generate rooted trees by size
by={1:[LEAF]}
def parts(total,maxsize):   # multisets of rooted trees with sizes summing to total, sizes nonincreasing
    if total==0: yield (); return
    for s in range(min(total,maxsize),0,-1):
        lst=by[s]
        for i,t in enumerate(lst):
            for rest in parts_from(total-s,s,i):
                yield (t,)+rest
def parts_from(total,s,i):
    # next elements: same size with index>=i, or smaller sizes
    if total==0: yield (); return
    if total>=s:
        for j in range(i,len(by[s])):
            for rest in parts_from(total-s,s,j): yield (by[s][j],)+rest
    for s2 in range(min(total,s-1),0,-1):
        for j in range(len(by[s2])):
            for rest in parts_from(total-s2,s2,j): yield (by[s2][j],)+rest
t0=time.time()
worst_tele=0; zero=[]; worst_gap=1; worst_rate={}; min_nonatom=(1,None); cnt=0
for n in range(2,NMAX+1):
    L=[]
    for p in parts_from(n-1,n-1,0):
        L.append(tuple(sorted(p)))
    by[n]=L
for n in range(1,NMAX+1):
    for b in by[n]:
        cnt+=1
        z,x,m=val(b); x=float(x)
        gg=g(b); d=delta(b)
        worst_tele=max(worst_tele,abs(gg-h(x)-d))
        if d<1e-13: zero.append(b)
        if not is_atom(b):
            worst_gap=min(worst_gap,d-DELTA0*nmin(b))
            if d<min_nonatom[0]: min_nonatom=(d,b)
        C=max(cap(b),1)
        for Cc in range(C,23):
            e=ETAS[Cc]; r=gg-e*n-(h(x)-e*w(x))
            worst_rate[Cc]=min(worst_rate.get(Cc,1),r)
    print(f"n={n}: {len(by[n])} rooted trees, cumulative {cnt}, {time.time()-t0:.0f}s",flush=True)
print("max |g-h-sum sigma| =",worst_tele)
print("zero-slack branches:",zero)
print("min over non-atoms of delta - 0.01426*#minimal non-atoms =",worst_gap)
print("min delta over non-atoms:",min_nonatom)
print("rate: min g-eta|R|-H(x) by cap:",{k:float("%.3e"%v) for k,v in worst_rate.items()})
